Use `pg` (node-postgres) with `Pool`. Key configs:

```js
import { Pool } from 'pg';

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                // max connections
  min: 2,                 // keep alive minimum
  idleTimeoutMillis: 30_000,     // kill idle connection after 30s
  connectionTimeoutMillis: 5_000, // fail fast if can't acquire connection
  allowExitOnIdle: true,         // let process exit cleanly when idle
});

// Catch pool-level errors (dropped connections, etc.)
pool.on('error', (err, client) => {
  console.error('Idle client error:', err);
});
```

**Query with error handling:**

```js
async function query(sql, params) {
  const client = await pool.connect(); // throws after connectionTimeoutMillis
  try {
    const result = await client.query(sql, params);
    return result.rows;
  } finally {
    client.release(); // always release — even on throw
  }
}
```

**Transaction wrapper:**

```js
async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

// Usage
await withTransaction(async (client) => {
  await client.query('INSERT INTO orders ...', [...]);
  await client.query('UPDATE inventory ...', [...]);
});
```

**Graceful shutdown:**

```js
process.on('SIGTERM', async () => {
  await pool.end(); // waits for active queries, then closes
  process.exit(0);
});
```

**Key rules:**
- Always `release()` in `finally` — leaked clients exhaust pool and hang
- `connectionTimeoutMillis` prevents indefinite queue pile-up under load
- `idleTimeoutMillis` avoids stale connections dropped by DB/firewall
- `max: 20` matches default Postgres `max_connections` headroom — tune per server
